import XCTest
@testable import StrandAnalytics
import WhoopProtocol

/// Tests the branched HR + motion day model (`Calories.estimateDayEnergy` with `motion`), the strength
/// damping and the Mifflin–St Jeor BMR. Fixtures are built block by block at 1 Hz and are identical in
/// the Kotlin twin `CaloriesMotionModelTest`, which pins the same literals (generated by this
/// implementation). APPROXIMATE estimates — not calorimetry, not medical advice.
final class CaloriesMotionModelTests: XCTestCase {

    private typealias Block = (seconds: Int, bpm: Int, intensity: Double?)
    private let h = 3_600
    private let profile = UserProfile(weightKg: 80, heightCm: 180, age: 35, sex: "male")

    /// 1 Hz HR and (where a block has an intensity) 1 Hz motion, blocks back to back from ts 0.
    private func build(_ blocks: [Block]) -> (hr: [HRSample], motion: [WorkoutDetector.ActivityPoint]) {
        var hr: [HRSample] = []
        var motion: [WorkoutDetector.ActivityPoint] = []
        var t = 0
        for b in blocks {
            for k in 0..<b.seconds {
                hr.append(HRSample(ts: t + k, bpm: b.bpm))
                if let i = b.intensity { motion.append(WorkoutDetector.ActivityPoint(ts: t + k, intensity: i)) }
            }
            t += b.seconds
        }
        return (hr, motion)
    }

    // Typical days (same fixtures as the Kotlin twin and the before/after report).
    // Sleep 52 bpm still, desk/sofa 66–70 bpm barely moving, walking ~98 bpm at the walk floor and above.
    private var walkingDay: [Block] {
        [(8 * h, 52, 0.01), (6 * h, 68, 0.03), (3 * h, 98, 0.25), (1 * h, 85, 0.12), (6 * h, 66, 0.03)]
    }
    /// Three hours at 128 bpm (above the 120 bpm HR-only gate) while sitting still: stress, caffeine, heat.
    private var stressDay: [Block] {
        [(8 * h, 52, 0.01), (3 * h, 128, 0.02), (5 * h, 70, 0.03), (8 * h, 66, 0.03)]
    }
    private var runDay: [Block] {
        [(8 * h, 52, 0.01), (45 * 60, 160, 0.55), (15 * 60, 115, 0.22), (8 * h, 68, 0.03), (7 * h, 66, 0.03)]
    }
    private var strengthHour: [Block] { [(1 * h, 135, 0.12)] }

    private func energy(_ blocks: [Block], withMotion: Bool,
                        strengthWindows: [ClosedRange<Int>] = []) -> Calories.DayEnergyEstimate {
        let (hr, motion) = build(blocks)
        return Calories.estimateDayEnergy(hr, profile: profile, hrmax: 185, restingHR: 55,
                                          motion: withMotion ? motion : [],
                                          strengthWindows: strengthWindows)
    }

    // MARK: - Mifflin–St Jeor

    func testMifflinStJeorReferenceValues() {
        // Hand-computed from the published equation (Mifflin et al. 1990), independent of the code:
        //   male    80 kg, 180 cm, 35 y: 800 + 1125   − 175 + 5   = 1755
        //   female  60 kg, 165 cm, 30 y: 600 + 1031.25 − 150 − 161 = 1320.25
        //   nonbinary (midpoint, −78)   70 kg, 170 cm, 30 y: 700 + 1062.5 − 150 − 78 = 1534.5
        let rest = (0..<86_400).map { HRSample(ts: $0, bpm: 50) }
        for (sex, w, ht, a, bmr) in [("male", 80.0, 180.0, 35.0, 1755.0),
                                     ("female", 60.0, 165.0, 30.0, 1320.25),
                                     ("nonbinary", 70.0, 170.0, 30.0, 1534.5)] {
            let p = UserProfile(weightKg: w, heightCm: ht, age: a, sex: sex)
            let e = Calories.estimateDayEnergy(rest, profile: p, hrmax: 185, restingHR: 55)
            XCTAssertEqual(e.restingKcal, bmr, accuracy: 1e-9, sex)
            XCTAssertEqual(e.activeKcal, 0, accuracy: 1e-12, sex)
        }
    }

    // MARK: - Branched model

    func testWalkingDayWithLowHRGetsMoreThanHROnly() {
        // 98 bpm is only 33% HRR: the HR-only gate (50%) counts the walk as rest, so the day is pure BMR.
        let hrOnly = energy(walkingDay, withMotion: false)
        let blended = energy(walkingDay, withMotion: true)
        XCTAssertEqual(hrOnly.activeKcal, 0, accuracy: 1e-12)
        XCTAssertEqual(blended.activeKcal, 925.388417125604, accuracy: 1e-9)
        XCTAssertGreaterThan(blended.totalKcal, hrOnly.totalKcal + 800)
        XCTAssertEqual(blended.restingKcal, hrOnly.restingKcal, accuracy: 1e-12,
                       "motion changes active energy only, never the resting floor")
    }

    func testHighHRWithoutMotionGetsLessThanHROnly() {
        let hrOnly = energy(stressDay, withMotion: false)
        let blended = energy(stressDay, withMotion: true)
        XCTAssertEqual(hrOnly.activeKcal, 1810.1339953064933, accuracy: 1e-9)
        XCTAssertEqual(blended.activeKcal, 452.5334988266233, accuracy: 1e-9)
        // Still (intensity ≤ the rest level) keeps exactly `dayStillHRWeight` of the HR-only estimate.
        XCTAssertEqual(blended.activeKcal, Calories.dayStillHRWeight * hrOnly.activeKcal, accuracy: 1e-9)
    }

    func testRunDayKeepsHRForTheRunAndAddsTheCooldownWalk() {
        let hrOnly = energy(runDay, withMotion: false)
        let blended = energy(runDay, withMotion: true)
        XCTAssertEqual(hrOnly.activeKcal, 670.7361756909139, accuracy: 1e-9)
        XCTAssertEqual(blended.activeKcal, 783.4215015801623, accuracy: 1e-9)
    }

    func testNoMotionIsIdenticalToHROnly() {
        // Empty motion must reproduce the HR-only path bit for bit, on every fixture.
        for blocks in [walkingDay, stressDay, runDay, strengthHour] {
            let (hr, _) = build(blocks)
            let plain = Calories.estimateDayEnergy(hr, profile: profile, hrmax: 185, restingHR: 55)
            let empty = Calories.estimateDayEnergy(hr, profile: profile, hrmax: 185, restingHR: 55, motion: [])
            XCTAssertEqual(plain, empty)
        }
        // And the values equal the pre-change HR-only estimator run with Mifflin coefficients
        // (scratch oracle of the old code): the motion branch adds nothing when it has no data.
        XCTAssertEqual(energy(stressDay, withMotion: false).activeKcal, 1810.1339953064933, accuracy: 1e-9)
        XCTAssertEqual(energy(strengthHour, withMotion: false).activeKcal, 667.0204458543164, accuracy: 1e-9)
    }

    func testCoarseMotionFallsBackToHROnly() {
        // A WHOOP 4.0 banks motion coarsely: one gravity record per 30 s covers 1/30 of each window,
        // below `dayMotionMinCoverage`, so every interval keeps the HR-only estimate.
        let (hr, motion) = build(stressDay)
        let coarse = motion.filter { $0.ts % 30 == 0 }
        let hrOnly = Calories.estimateDayEnergy(hr, profile: profile, hrmax: 185, restingHR: 55)
        let withCoarse = Calories.estimateDayEnergy(hr, profile: profile, hrmax: 185, restingHR: 55,
                                                    motion: coarse)
        XCTAssertEqual(withCoarse, hrOnly)
    }

    func testBothSignalsLowStaysAtTheRestingFloor() {
        let sofa: [Block] = [(2 * h, 66, 0.03)]
        XCTAssertEqual(energy(sofa, withMotion: true).activeKcal, 0, accuracy: 1e-12)
    }

    func testMotionMETAnchors() {
        XCTAssertEqual(Calories.motionMET(0.0), 1.0, accuracy: 1e-12)
        XCTAssertEqual(Calories.motionMET(0.05), 1.0, accuracy: 1e-12)
        XCTAssertEqual(Calories.motionMET(0.15), 2.75, accuracy: 1e-12)
        XCTAssertEqual(Calories.motionMET(0.20), 3.5, accuracy: 1e-12)
        XCTAssertEqual(Calories.motionMET(0.40), 5.25, accuracy: 1e-12)
        XCTAssertEqual(Calories.motionMET(2.0), 7.0, accuracy: 1e-12, "capped at the top anchor")
    }

    // MARK: - Strength

    func testStrengthBoutIsDamped() {
        let (hr, _) = build(strengthHour)
        let plain = Calories.estimateBoutCalories(hr, profile: profile, hrmax: 185, restingHR: 55).0
        let strength = Calories.estimateBoutCalories(hr, profile: profile, hrmax: 185, restingHR: 55,
                                                     strength: true).0
        XCTAssertEqual(plain, 740.1454458543643, accuracy: 1e-9)
        XCTAssertEqual(strength, 518.1018120980475, accuracy: 1e-9)
        XCTAssertEqual(strength, plain * Calories.strengthKeytelFactor, accuracy: 1e-6,
                       "at 135 bpm the damped rate stays above the resting floor, so it is a plain 0.7×")
    }

    func testStrengthBoutNeverDropsBelowResting() {
        // At a HR just over the bout gate the damped Keytel rate would fall under BMR; the floor holds.
        let hr = (0..<600).map { HRSample(ts: $0, bpm: 95) }
        let restOnly = Calories.estimateBoutCalories((0..<600).map { HRSample(ts: $0, bpm: 60) },
                                                     profile: profile, hrmax: 185, restingHR: 55).0
        let strength = Calories.estimateBoutCalories(hr, profile: profile, hrmax: 185, restingHR: 55,
                                                     strength: true).0
        XCTAssertGreaterThanOrEqual(strength, restOnly - 1e-9)
    }

    func testStrengthWindowDampsTheDay() {
        let window = [0...(h - 1)]
        XCTAssertEqual(energy(strengthHour, withMotion: false, strengthWindows: window).activeKcal,
                       444.97681209804904, accuracy: 1e-9)
        XCTAssertEqual(energy(strengthHour, withMotion: true).activeKcal, 442.06249882184744, accuracy: 1e-9)
        XCTAssertEqual(energy(strengthHour, withMotion: true, strengthWindows: window).activeKcal,
                       308.7376325086525, accuracy: 1e-9)
        // A window elsewhere in the day changes nothing.
        XCTAssertEqual(energy(strengthHour, withMotion: false, strengthWindows: [(10 * h)...(11 * h)]),
                       energy(strengthHour, withMotion: false))
    }

    func testIsStrengthSport() {
        for s in ["Strength", "Strength Training", "TraditionalStrengthTraining", "Weightlifting",
                  "Powerlifting", "Bodybuilding", "functional strength training"] {
            XCTAssertTrue(Calories.isStrengthSport(s), s)
        }
        for s in ["Running", "Walking", "Cycling", "HIIT", "Yoga", ""] {
            XCTAssertFalse(Calories.isStrengthSport(s), s)
        }
        XCTAssertFalse(Calories.isStrengthSport(nil))
    }

    // MARK: - analyzeDay wiring

    // 2026-01-02T12:00:00Z, safely inside UTC day 2026-01-02.
    private let dayUtc = "2026-01-02"
    private let noonUtc = 1_767_355_200

    /// One hour at `bpm` from noon, with gravity alternating by `step` g each second (intensity = step).
    private func noonHour(bpm: Int, step: Double) -> (hr: [HRSample], gravity: [GravitySample]) {
        let hr = (0..<h).map { HRSample(ts: noonUtc + $0, bpm: bpm) }
        let gravity = (0..<h).map { GravitySample(ts: noonUtc + $0, x: $0 % 2 == 0 ? 0 : step, y: 0, z: 1) }
        return (hr, gravity)
    }

    func testAnalyzeDayUsesGravityForTheDayTotal() throws {
        let walk = noonHour(bpm: 98, step: 0.25)
        let hrOnly = try XCTUnwrap(AnalyticsEngine.analyzeDay(
            day: dayUtc, hr: walk.hr, profile: profile, maxHROverride: 185).daily.activeKcalEst)
        let withMotion = try XCTUnwrap(AnalyticsEngine.analyzeDay(
            day: dayUtc, hr: walk.hr, dayGravity: walk.gravity, profile: profile,
            maxHROverride: 185).daily.activeKcalEst)
        XCTAssertGreaterThan(withMotion, hrOnly, "a walk at low HR must add energy once motion is seen")

        let still = noonHour(bpm: 150, step: 0)
        let stillHROnly = try XCTUnwrap(AnalyticsEngine.analyzeDay(
            day: dayUtc, hr: still.hr, profile: profile, maxHROverride: 185).daily.activeKcalEst)
        let stillWithMotion = try XCTUnwrap(AnalyticsEngine.analyzeDay(
            day: dayUtc, hr: still.hr, dayGravity: still.gravity, profile: profile,
            maxHROverride: 185).daily.activeKcalEst)
        XCTAssertLessThan(stillWithMotion, stillHROnly, "high HR while still must count for less")
    }

    func testAnalyzeDayDampsEnteredStrengthWorkouts() throws {
        let lift = noonHour(bpm: 150, step: 0)
        let plain = try XCTUnwrap(AnalyticsEngine.analyzeDay(
            day: dayUtc, hr: lift.hr, profile: profile, maxHROverride: 185).daily.activeKcalEst)
        let damped = try XCTUnwrap(AnalyticsEngine.analyzeDay(
            day: dayUtc, hr: lift.hr, strengthWorkoutWindows: [noonUtc...(noonUtc + h - 1)],
            profile: profile, maxHROverride: 185).daily.activeKcalEst)
        XCTAssertLessThan(damped, plain)
    }
}
